        clauses.append(clause)

    # Build implication graph for 2-SAT
    # Each variable xi has nodes 2*(i-1) (for ¬xi) and 2*(i-1)+1 (for xi)
    num_nodes = 2 * m
    graph = [[] for _ in range(num_nodes)]

    for clause in clauses:
        lit_vars = []  # [(lit_value, node_index), ...]
        for lit in clause:
            var = abs(lit) - 1  # 0-indexed
            node = 2 * var + (1 if lit > 0 else 0)
            lit_vars.append((lit, node))

        if len(lit_vars) <= 2:
            # Standard 2-SAT clause: (a OR b) -> edges: ¬a -> b, ¬b -> a
            for i, (_, u) in enumerate(lit_vars):
                for j, (_, v) in enumerate(lit_vars):
                    if i != j:
                        # Edge from ¬u to v
                        neg_node = u ^ 1
                        graph[neg_node].append(v)
                    else:
                        # Edge from ¬u to u itself
