    for clause in clauses:
        lits = []
        for lit in clause:
            var = abs(lit) - 1
            node = 2 * var + (1 if lit > 0 else 0)
            lits.append((lit, node))
        # For any clause with k literals, if all k are false, clause is violated
        # We need: for each pair (li, lj), add edge ¬li -> lj
        # This ensures at least one literal is true (via transitivity)
        for k_lit, lit in enumerate(clause):
            for other_lit in clause:
                if k_lit != clause.index(other_lit):
                    var1 = abs(lit) - 1
                    node1 = 2 * var1 + (1 if lit > 0 else 0)
                    neg_node1 = node1 ^ 1

                    var2 = abs(other_lit) - 1
                    node2 = 2 * var2 + (1 if other_lit > 0 else 0)
                    complete_graph[neg_node1].append(node2)

    # Build transitive closure for each variable's implications
    # Use Floyd-Warshall-like propagation limited by "appears at most twice"

    # For 2-SAT, verify satisfiability using SCC
    # Using Kosaraju's algorithm
    visited_scc = [False] * num_nodes
    order = []

    def dfs1(u):
        visited_scc[u] = True
        for v in complete_graph[u]:
            if not visited_scc[v]:
                dfs1(v)
        order.append(u)

    for i in range(num_nodes):
        if not visited_scc[i]:
            dfs1(i)

    # Build transpose graph
    transpose_graph = [[] for _ in range(num_nodes)]
    for u in range(num_nodes):
        for v in complete_graph[u]:
            transpose_graph[v].append(u)

    comp = [-1] * num_nodes
    comp_count = 0

    def dfs2(u):
        comp[u] = comp_count
        for v in transpose_graph[u]:
            if comp[v] == -1:
                dfs2(v)

    for i in reversed(order):
        if comp[i] == -1:
            dfs2(i)
            comp_count += 1

    # Check if any variable and its negation are in same component
    for i in range(m):
        if comp[2 * i] == comp[2 * i + 1]:
            return "NO"

    # Construct satisfying assignment
    assignment = ['0'] * m
    for i in range(m):
        if comp[2 * i + 1] < comp[2 * i]:
            assignment[i] = '1'

    result = "YES\n" + "".join(assignment)
    return result

