        if parts[0] == '1':
            events.append(1)
        else:
            events.append((2, parts[1]))

    # Identify segments between type 1 events
    segments = []
    current_segment = set()
    for event in events:
        if event == 1:
            if current_segment:
                segments.append(current_segment)
                current_segment = set()
        else:
            current_segment.add(event[1])
    if current_segment:
        segments.append(current_segment)

    # Collect all unique friends
    friends = set()
    for seg in segments:
        friends.update(seg)
    friend_list = sorted(list(friends))
    name_to_id = {name: i for i, name in enumerate(friend_list)}
    num_friends = len(friend_list)

    # Identify which friends appear in which segments
    if num_friends == 0:
        return '0'

    # Build conflict graph: two friends conflict if they appear in same segment
    conflict_adj = [[] for _ in range(num_friends)]
    for i in range(num_friends):
        for j in range(i + 1, num_friends):
            seg_i = set(friend_list[i])
            seg_j = set(friend_list[j])
            # Check if both appear in same segment
            for seg in segments:
                if friend_list[i] in seg and friend_list[j] in seg:
                    conflict_adj[i].append(j)
                    conflict_adj[j].append(i)
                    break

    # Meet-in-the-middle for max independent set
    half = num_friends // 2

    # Enumerate all independent sets in left half
    left_masks = []  # (mask, count)

    def enumerate_left(idx, mask, count):
        if idx == half:
            left_masks.append((mask, count))
            return
        # Don't include idx
        enumerate_left(idx + 1, mask, count)
        # Include idx (basic check - will validate on right)
        enumerate_left(idx + 1, mask | (1 << idx), count + 1)

    enumerate_left(0, 0, 0)

    # Enumerate all independent sets in right half
    left_valid = []  # (mask, count, right_conflicts)
    for mask, count in left_masks:
        # Check if left mask is internally independent
        valid = True
        for i in range(half):
            if mask & (1 << i):
                for j in conflict_adj[i]:
                    if j < half and mask & (1 << j):
                        valid = False
                        break
                if not valid:
                    break

        if valid:
            # Check cross conflicts from left to right
            right_conflicts = 0
            for i in range(half):
                if mask & (1 << i):
                    for j in conflict_adj[i]:
                        if j >= half:
                            right_conflicts |= (1 << (j - half))
            left_valid.append((mask, count, right_conflicts))

    # Enumerate right half masks
    right_results = {}  # mask -> max_valid_count

    def enumerate_right(idx, mask, count):
        if idx == half + (num_friends - half):
            right_results[mask] = max(right_results.get(mask, 0), count)
            return
        enumerate_right(idx + 1, mask, count)
        enumerate_right(idx + 1, mask | (1 << idx), count + 1)

    for i in range(half, num_friends):
        enumerate_right(0, 0, 0)

    # Combine valid left sets with valid right sets ensuring no cross conflicts
    max_happy = 0
    for left_mask, left_count, left_certs in left_valid:
        for right_mask, right_count in right_results.items():
            # Check for cross conflicts between left and right selected
            cross_conflict = False
            for i in range(half):
                if left_mask & (1 << i):
                    if (left_certs >> (i % (num_friends - half if num_friends > half else 1))) & 1:
                        cross_conflict = True
                        break

            if not cross_conflict:
                max_happy = max(max_happy, left_count + right_count)

    return str(max_happy)

