            idx += 1

        if idx >= len(lines):
            break

        n = int(lines[idx])
        idx += 1

        tree = []  # store children as (L, R) or (-1, -1) for leaf
        leaves_value = []

        for i in range(n):
            parts = list(map(int, lines[idx].split()))
            idx += 1
            if parts[0] == -1:
                # non-leaf: children are parts[1] and parts[2]
                l, r = parts[1], parts[2]
                tree.append((l, r))
                leaves_value.append(-1)
            else:
                # leaf: value is parts[0]
                tree.append((-1, -1))
                leaves_value.append(parts[0])

        # Compute L[u]: number of leaves in subtree u
        L = [0] * n
        for i in range(n):
            if leaves_value[i] != -1:
                L[i] = 1
            else:
                L[i] = 0

        # Process in reverse to accumulate leaf counts from children to parents
        for i in range(n - 1, -1, -1):
            if leaves_value[i] == -1:  # non-leaf
                l, r = tree[i]
                L[i] = L[l] + L[r]

        # Compute values using DP
        values = []
        for i in range(n):
            if leaves_value[i] != -1:
                values.append(leaves_value[i])
            else:
                l, r = tree[i]
                # Moves in subtree = L[i] - 1
                # Odd: Pieguy moves last → use max
                # Even: Piegirl moves last → use min
                mv = L[i] - 1
                if mv % 2 == 1:
                    values.append(max(values[l], values[r]))
                else:
                    values.append(min(values[l], values[r]))

        results.append(str(values[0]))

    return '\n'.join(results)

