def solution(grid_input):
    """
    Determine who wins the chocolate game on a hexagonal grid.
    Karlsson goes first. The player who cannot make a move loses.
    """
    import sys
    import os

    # Parse the hexagonal grid
    lines = grid_input.strip().split('\n')

    # Extract all cells (only 'O' and '.')
    cells = []
    coords = []
    for i, line in enumerate(lines):
        for j, c in enumerate(line):
            if c in '.O':
                cells.append(c)
                coords.append((i, j))

    if not cells or all(c != 'O' for c in cells):
        # No chocolates, first player loses
        return "Lillebror\n"

    n = len(cells)

    # Build adjacency for hexagonal grid
    # Using a standard hexagonal coordinate system
    # Each cell knows its neighbors
    neighbors = {}

    for idx, (row, col) in enumerate(coords):
        neighs = []
        # Hexagonal grid has 6 directions
        directions = [(-1, 0), (-1, 1), (0, 1), (1, 1), (1, 0), (0, -1)]
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < len(lines) and 0 <= nc < len(lines[nr]):
                # Find this position's coordinate index
                for k, (r, c) in enumerate(coords):
                    if r == nr and c == nc:
                        neighs.append(k)
                        break
        neighbors[idx] = neighs

    # Use minimax with memoization
    memo = {}

    def can_win(state_tuple):
        if state_tuple in memo:
            return memo[state_tuple]

        state_list = list(state_tuple)
        if '.' not in state_list or all(c == '.' for c in state_list):
            memo[state_tuple] = False
            return False

        # Find all valid moves (removing consecutive adjacent chocolates)
        next_states = []

        for start in range(n):
            if state_list[start] != 'O':
                continue

            # Try removing chains starting from position 'start'
            chain = [start]
            pos = coords[start]

            # Expand in all hexagonal directions
            changed = True
            while changed:
                changed = False
                new_chain = list(chain)
                for dir_idx in range(6):
                    dir_neighbors = neighbors.get(chain[-1], [])
                    for neighbor in dir_neighbors:
                        if neighbor not in chain and state_list[neighbor] == 'O':
                            new_chain.append(neighbor)
                            chain = new_chain
                            changed = True
                            break

            if len(set(chain)) >= 2:
                # Valid chain - remove it
                new_state = list(state_tuple)
                for neg in chain:
                    if 0 <= neg < n:
                        new_state[neg] = '.'
                next_states.append(tuple(new_state))

        if not next_states:
            memo[state_tuple] = False
            return False

        # If any move leads to opponent losing, current player wins
        for ns in next_states:
            if not can_win(ns):
                memo[state_tuple] = True
                return True
        memo[state_tuple] = False
        return False

    # Karlsson wins if there's a winning strategy from the initial state
    initial_state = tuple(cells)
    result = can_win(initial_state)

    return "Karlsson\n" if result else "Lillebror\n"


