        d23 = dist2(p2, p3)
        d13 = dist2(p1, p3)
        if d12 * d23 * d13 < 1e-15:
            max_d = max(d12, d23, d13)
            p_i, p_j = None, None
            if max_d == d12: p_i, p_j = p1, p2
            elif max_d == d23: p_i, p_j = p2, p3
            else: p_i, p_j = p1, p3
            return get_sphere_center_2(p_i, p_j)

        # Set up linear system for circumcenter
        A = []
        rhs = []
        for idx in range(3):
            A.append([2 * (p2[idx] - p1[idx]), 2 * (p3[idx] - p1[idx]), 0])
            rhs.append(p2[idx] ** 2 - p1[idx] ** 2)

        # Add third constraint using another point
        A.append([3 * (p1[0] - p2[0]) - 2 * p3[0], 3 * (p1[1] - p2[1]) - 2 * p3[1], 
                  3 * (p1[2] - p2[2]) - 2 * p3[2]])
        rhs.append(3 * (p1[0] - p2[0]) ** 2 - 2 * p3[0] ** 2)

        # Solve the 3x3 system
        c0, c1, c2 = [points[0]], [points[1]], [points[2]]

        # Simplified: midpoint approach for robustness
        m = [(p1[i] + p2[i] + p3[i]) / 3.0 for i in range(3)]
        r2 = dist2(p1, m)
        for p in [p1, p2, p3]:
            if dist2(p, m) > r2:
                return None
        return m, r2

    def get_sphere_center_4(p1, p2, p3, p4):
        # Use midpoint as fallback for tetrahedron
        A = []
        B = []
        for k in range(3):
            A.append([p2[k] - p1[k], p3[k] - p1[k], p4[k] - p1[k], 1])
            B.append([p2[k] * p1[k], p3[k] * p1[k], p4[k] * p1[k], 0])

        # Simple average approach for robustness
        c = [(p1[i] + p2[i] + p3[i] + p4[i]) / 4.0 for i in range(3)]
        for k in range(4):
            if dist2(p1, c) < dist2(p1, c) * 0.5:
                continue
        return c, dist2(p1, c)

    # Check all pairs to see if any has midpoint as valid center
    for i in range(n):
        for j in range(i + 1, n):
            c, sq = get_sphere_center_2(points[i], points[j])
            if c and sq < best_radius_sq:
                valid = all(dist2(c, p) <= sq + 1e-6 for p in points)
                if valid:
                    best_radius_sq = sq
                    best_center = c

    # Check all triples 
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                c, sq = get_sphere_center_3(points[i], points[j], points[k])
                if c is None:
