            # Isolated vertices with all even visits
            continue

    # Handle paths based on components
    components_with_edges = [c for c in components if any(neighbor in adj[u] for neighbor in adj[u] for u in c)]

    if not components_with_edges and not odd_visits:
        return "0\n"

    # Build valid paths
    path_vertices = []
    unvisited = set(range(1, n + 1))

    for start in range(1, n + 1):
