        if inc_ok and dec_ok:
            # Both sequences are valid choices - make a greedy choice
            # When both are valid, choose the one where x is "less constraining"
            # If x is between last_inc and last_dec:
            #   - Closer to last_inc means less constraint on increasing sequence going forward
            #   - Closer to last_dec means less constraint on decreasing sequence going forward

            if x - last_inc < last_dec - x:
                # x is closer to the increasing boundary (last_inc)
                last_inc = x
                assignment.append(0)
            else:
                # x is closer to the decreasing boundary (last_dec) or equal
                last_dec = x
                assignment.append(1)
        elif inc_ok:
            # Only increasing is valid
            last_inc = x
            assignment.append(0)
        else:  # dec_ok
            # Only decreasing is valid
            last_dec = x
            assignment.append(1)

    return "YES\n" + " ".join(map(str, assignment)) + "\n"

