        else:
            return float('inf')

    # Check a strategic set of time points
    candidates = set()
    candidates.add(ts)

    # Add times just before and after each visitor arrival
    for v in visitors:
        if v >= ts and v <= tf - t:
            candidates.add(v)
            candidates.add(v - 1)
            candidates.add(v + 1)

    # Also check when receptionist becomes free after each visitor
    current_free = ts
    for v in visitors[:n]:
        if v >= current_free:
            current_free = v + t
        if current_free < tf:
            break
    if current_free <= tf - t:
        candidates.add(current_free)

    # AddLast possible service completion time
    if ts + t <= tf:
        candidates.add(ts)

    min_wait = float('inf')
    best_time = ts

    for arr_time in candidates:
        if arr_time < ts or arr_time > tf or arr_time + t > tf:
