    n = int(lines[0])
    x = list(map(int, lines[1].split()))
    a, b = map(int, lines[2].split())

    # BFS from a down to b
    dist = {a: 0}
    heap = [(0, a)]

    while heap:
        d, v = heapq.heappop(heap)

        if v == b:
            return f"{d}\n"

        if dist.get(v, float('inf')) < d:
            continue

        # Move 1: subtract 1
        if v - 1 >= b:
            if d + 1 < dist.get(v - 1, float('inf')):
                dist[v - 1] = d + 1
                heapq.heappush(heap, (d + 1, v - 1))

        # Move 2: subtract v mod xi
        # Use deduplication for efficiency
        for xi in x:
            mod = v % xi
            new_v = v - mod
            if new_v >= b:
                if d + 1 < dist.get(new_v, float('inf')):
                    dist[new_v] = d + 1
                    heapq.heappush(heap, (d + 1, new_v))

    return "0\n"

