class LiChaoTree:
    def __init__(self, size):
        # Size for domain
        self.size = 1
        while self.size < size:
            self.size *= 2
        self.tree = [None] * (4 * self.size)
        self.active_count = [0] * (4 * self.size)

    def _add_line(self, node, l, r, line):
        if self.active_count[node] > 0:
            mid = (l + r) // 2

            # Get current best line at mid
            mid_val = self.tree[node].eval(mid)
            line_at_mid = line.eval(mid)

            if line_at_mid > mid_val:
                # Swap
                self.tree[node], line = line, self.tree[node]
                self.tree[node].active = True
                line.active = False

            if l == r:
                return

            ll_val = self.tree[node].eval(l)

            if line.active and line.eval(l) > self.tree[node].eval(l):
                self._add_line(node * 2, l, mid, line)
            elif line.active and line.eval(r) > self.tree[node].eval(r):
                self._add_line(node * 2 + 1, mid + 1, r, line)
            del line
        else:
            if line.eval(l * line.a + line.b) > line.a * line.a + line.b:
                self.tree[node] = line
                self.tree[node].active = True
            else:
                self.tree[node] = line
                self.tree[node].active = False

    def _query(self, node, l, r, q):
        if self.tree[node] is None:
            return -float('inf')
        res = self.tree[node].eval(q)
        if l == r:
            return res
        mid = (l + r) // 2
        if q <= mid:
            return max(res, self._query(node * 2, l, mid, q))
        else:
            return max(res, self._query(node * 2 + 1, mid + 1, r, q))

    def add(self, line):
        self._add_line(1, 0, self.size - 1, line)

    def query(self, q):
        return self._query(1, 0, self.size - 1, q)

