    def pow_mod(base, exp):
        result = 1
        base %= MOD
        while exp > 0:
            if exp % 2 == 1:
                result = result * base % MOD
            base = base * base % MOD
            exp //= 2
        return result

    def inverse(n):
        return pow_mod(n, MOD - 2)

    def nCr(n, r, fact, invFact):
        if r < 0 or r > n:
            return 0
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD

