    invFact = [1] * size
    invFact[size - 1] = inverse(fact[size - 1])
    for i in range(size - 2, -1, -1):
        invFact[i] = invFact[i + 1] * (i + 1) % MOD

    # Using the formula: E[L] = l * C(2n+1, n+k) * (C(2n+1, k))^{-1}
